function UIJackpotDungoenReviewDialog:InitData()
    self._data = {}
    local t = HalloweenUtils.GetAllPlot(self._activityId)
    for k, v in pairs(t) do
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(v)
        local isUnlock = HalloweenUtils.IsUnlockRewardPool(vo.PoolId)
        if isUnlock then
            table.insert(self._data, vo)
        end
    end
end

function UIJackpotDungoenReviewDialog:FillSelf()
    self.LoopList:InitListView(#self._data, Bind(self, self.OnGetCellByIndex))
end

function UIJackpotDungoenReviewDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local vo = self._data[index + 1]

    local rootGo = cell.gameObject.transform:Find("Item")
    CfUtils.FillText(rootGo.transform:Find("TxtNumber/TxtDesc"), vo.name)

    SetButtonAction(rootGo.transform:Find("FontStyleButton"), function()
        self:PlayPlot(vo.id)
    end)
    return cell
end

--播放剧情
function UIJackpotDungoenReviewDialog:PlayPlot(id, endCb)
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true
    local plotVo = QuestConfMgr:GetInstance():GetQuestVoById(id)

    local plotIds = CfUtils.Split(plotVo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, endCb)
end

function UIJackpotDungoenReviewDialog:PlayPloting(plotIds, endCb)
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        CS.UINavigationBarRoot.Instance:SetActive(false)
        self._plotGo = go
    end, function()
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            if endCb then
                endCb()
            end

            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            CS.UINavigationBarRoot.Instance:SetActive(true)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false

            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.PlayMusicById("bgm_instance_halloween")
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, endCb)
        end
    end)
end

